var tree = get_tree()
var scene = tree.current_scene
Engine.max_fps = 120
var set_vector = func(v: Vector2):
	for axis in [JOY_AXIS_RIGHT_X, JOY_AXIS_RIGHT_Y]:
		var event = InputEventJoypadMotion.new()
		event.device = 0
		event.axis = axis
		event.axis_value = v.x if axis == JOY_AXIS_RIGHT_X else v.y
		Input.parse_input_event(event)
var wait_frames = func(count: int):
	for frame in range(count):
		await tree.process_frame
set_vector.call(Vector2.ZERO)
await wait_frames.call(3)
var results = []
for value in [0.599,0.6,0.601]:
	var before = scene.log_rows.size()
	set_vector.call(Vector2(value,0.0))
	await wait_frames.call(3)
	set_vector.call(Vector2.ZERO)
	await wait_frames.call(3)
	results.append({"activation":value,"samples":scene.log_rows.size()-before})
var before = scene.log_rows.size()
var checkpoints = []
for value in [0.95,0.251,0.95,0.25,0.95,0.0]:
	set_vector.call(Vector2(value,0.0))
	await wait_frames.call(3)
	checkpoints.append(scene.log_rows.size()-before)
return {"activation":results,"hysteresis_counts":checkpoints,"hysteresis_expected":[1,1,1,1,2,2]}
